param([string]$EnvFile='.\.env',[long[]]$Ids=@(14006,16011,15004,15010,302,299,298,3020,288))
$ErrorActionPreference='Stop';$v=@{};Get-Content $EnvFile|Where-Object{$_ -match '^[^#].*='}|ForEach-Object{$p=$_ -split '=',2;$v[$p[0].Trim()]=$p[1].Trim()};foreach($n in @('GK_SITE_URL','GK_UNIFIED_API_TOKEN')){if([string]::IsNullOrWhiteSpace($v[$n])){throw "$n fehlt."}}
$site=$v['GK_SITE_URL'].TrimEnd('/');$h=@{Authorization='Bearer '+$v['GK_UNIFIED_API_TOKEN']};$root=if(Test-Path(Join-Path $PSScriptRoot '..\GkProductionWorker.sln')){Split-Path -Parent $PSScriptRoot}else{$PSScriptRoot};$out=Join-Path $root 'review-batch';New-Item $out -ItemType Directory -Force|Out-Null
foreach($id in $Ids){$body=[Text.Encoding]::UTF8.GetBytes((@{id=$id}|ConvertTo-Json -Compress));$post=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/read-post') -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body $body;$html=[string]$post.content;$images=@([regex]::Matches($html,'(?is)<img\b[^>]*(?:src|data-src)\s*=\s*["''](?<url>[^"'']+)["''][^>]*>')|ForEach-Object{[ordered]@{url=[Net.WebUtility]::HtmlDecode($_.Groups['url'].Value);html=$_.Value}});$headings=@([regex]::Matches($html,'(?is)<h(?<level>[1-6])\b[^>]*>(?<text>.*?)</h\k<level>>')|ForEach-Object{[ordered]@{level=[int]$_.Groups['level'].Value;text=([Net.WebUtility]::HtmlDecode([regex]::Replace($_.Groups['text'].Value,'<[^>]+>',' ')) -replace '\s+',' ').Trim()}});[ordered]@{id=$id;title=[string]$post.title;status=[string]$post.status;images=$images;headings=$headings;content=$html;raw=$post}|ConvertTo-Json -Depth 20|Set-Content(Join-Path $out("post-$id.json"))-Encoding UTF8;$metadata=[ordered]@{};foreach($property in $post.PSObject.Properties){if($property.Name -ne 'content'){$metadata[$property.Name]=$property.Value}};Write-Host('METADATEN: '+($metadata|ConvertTo-Json -Depth 10 -Compress));Write-Host("EXPORTIERT: $id | Bilder="+$images.Count+' | Überschriften='+$headings.Count)}
